INSERT INTO _migration_619_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_bece_intsci_s3_001', 'topic_bece_science_cells', 'subj_bece_science', 'exam_bece', NULL, NULL, 'A red blood cell bursts when placed in pure water, but a plant cell kept in pure water does not. Which structure explains the difference?', 'multiple_choice', NULL, '["A. The cellulose cell wall, which resists the extra water pressure","B. The nucleus, which pumps water out of the plant cell","C. The chloroplasts, which absorb the extra water","D. The cell membrane, which is thicker in plant cells"]', 'A', 'Water enters both cells by osmosis. The plant cell has a tough cellulose cell wall outside its membrane; as water enters, the wall resists the pressure, so the cell becomes firm (turgid) but does not burst. The red blood cell has no wall, so it swells and bursts. (The nucleus controls cell activities but cannot pump out water; chloroplasts make food and do not absorb the inflow; plant and animal cell membranes are similarly thin.) Therefore the correct answer is A: The cellulose cell wall, which resists the extra water pressure.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO3', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_002', 'topic_bece_science_cells', 'subj_bece_science', 'exam_bece', NULL, NULL, 'Pieces of peeled cassava are placed in a concentrated salt solution. After one hour the pieces have become soft and have shrunk slightly. Which statement explains this?', 'multiple_choice', NULL, '["A. Water moved by osmosis from the salt solution into the cassava cells","B. Water moved by osmosis from the cassava cells into the stronger salt solution","C. Salt moved into the cells and dissolved their contents","D. The cassava absorbed salt, which made the cells firm"]', 'B', 'Osmosis moves water across a partially permeable membrane from the weaker (more dilute) solution to the stronger (more concentrated) one. The concentrated salt solution draws water out of the cassava cells, so they lose turgor and the pieces go soft. (Water moving in would make the pieces firm, not soft; salt does not dissolve the cell contents.) Therefore the correct answer is B: Water moved by osmosis from the cassava cells into the stronger salt solution.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO3', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_003', 'topic_bece_science_cells', 'subj_bece_science', 'exam_bece', NULL, NULL, 'State two structural differences between a typical plant cell and a typical animal cell.', 'short_answer', NULL, NULL, 'A plant cell has a cellulose cell wall and chloroplasts (and usually a large central vacuole); an animal cell has none of these structures.', 'A typical plant cell is surrounded by a cellulose cell wall, contains chloroplasts for photosynthesis and usually has one large central vacuole. An animal cell has only a cell membrane, no chloroplasts and only small temporary vacuoles. Any two of these differences earn the marks. Answer: plant cells have a cell wall and chloroplasts (and a large central vacuole); animal cells do not.', 'medium', '2', '2', '90', NULL, NULL, '1', NULL, NULL, 'State', 'AO1', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_004', 'topic_bece_science_cells', 'subj_bece_science', 'exam_bece', NULL, NULL, 'A diagram of a cell measures 45 mm across. The real cell is 0.15 mm across. Calculate the magnification of the diagram.', 'calculation', NULL, NULL, '×300', 'Magnification = size of image ÷ real size of object = 45 mm ÷ 0.15 mm = 300. The diagram is 300 times larger than the real cell. Answer: ×300.', 'medium', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_005', 'topic_bece_science_cells', 'subj_bece_science', 'exam_bece', NULL, NULL, 'Ama is studying how substances move into and out of cells.', 'structured', NULL, NULL, '(a) Diffusion is the movement of particles from a region of higher concentration to a region of lower concentration until they are evenly spread (1). (b) Any two of: temperature — a higher temperature gives faster diffusion (1); the concentration difference (gradient) between the two regions (1); the distance over which diffusion must occur; the size of the particles (1). (c) Amoeba is microscopic, so oxygen and nutrients reach every part of its single cell by diffusion over a very short distance (1). A human is large and made of many cells, so diffusion alone would be far too slow; a blood circulatory system is needed to carry materials quickly to all cells (1).', '(a) Diffusion is the movement of particles from a region of higher concentration to a region of lower concentration until they are evenly spread (1). (b) Any two of: temperature — a higher temperature gives faster diffusion (1); the concentration difference (gradient) between the two regions (1); the distance over which diffusion must occur; the size of the particles (1). (c) Amoeba is microscopic, so oxygen and nutrients reach every part of its single cell by diffusion over a very short distance (1). A human is large and made of many cells, so diffusion alone would be far too slow; a blood circulatory system is needed to carry materials quickly to all cells (1).', 'medium', '5', '5', NULL, NULL, NULL, '1', NULL, NULL, 'Explain', 'AO2', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_006', 'topic_bece_science_body', 'subj_bece_science', 'exam_bece', NULL, NULL, 'Why does the wall of the left ventricle of the heart have thicker muscle than the wall of the right ventricle?', 'multiple_choice', NULL, '["A. It receives blood from both lungs at once","B. It pumps blood a shorter distance to the lungs","C. It must pump blood at higher pressure round the whole body","D. It contains more valves that need support"]', 'C', 'The left ventricle pumps oxygenated blood through the aorta to the entire body, a long distance that needs high pressure, so its muscular wall is the thickest. The right ventricle pumps blood only to the nearby lungs at lower pressure. (Pumping to the lungs is the right side’s job; valves are thin flaps that prevent backflow and do not need thick muscle to support them.) Therefore the correct answer is C: It must pump blood at higher pressure round the whole body.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO3', NULL, NULL, 'board_waec'),
('q_bece_intsci_s3_007', 'topic_bece_science_body', 'subj_bece_science', 'exam_bece', NULL, NULL, 'During a game of football, Kofi’s breathing becomes faster and deeper. What is the main reason for this change?', 'multiple_choice', NULL, '["A. His lungs are resting, so they work more slowly","B. His body temperature falls and the lungs keep him warm","C. His heart stops, so the lungs take over its work","D. His muscles need more oxygen and produce more carbon dioxide that must be removed"]', 'D', 'Exercise raises the rate of respiration in the muscle cells, using up more oxygen and releasing more carbon dioxide. Faster, deeper breathing supplies the extra oxygen and expels the extra carbon dioxide. (The lungs do not rest during exercise; breathing is not controlled by body temperature falling, and the heart beats faster rather than stopping.) Therefore the correct answer is D: His muscles need more oxygen and produce more carbon dioxide that must be removed.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO3', NULL, NULL, 'board_waec');
INSERT INTO _migration_619_expected_parts (id, question_id, part_label, part_text, marks, correct_answer, display_order) VALUES ('sqp_q_bece_intsci_s3_005_a', 'q_bece_intsci_s3_005', 'a', 'Define the term diffusion.', '1', 'Diffusion is the movement of particles from a region of higher concentration to a region of lower concentration until they are evenly spread (1).', '1'),
('sqp_q_bece_intsci_s3_005_b', 'q_bece_intsci_s3_005', 'b', 'State two factors that affect the rate of diffusion.', '2', 'Any two of: temperature — a higher temperature gives faster diffusion (1); the concentration difference (gradient) between the two regions (1); the distance over which diffusion must occur; the size of the particles (1).', '2'),
('sqp_q_bece_intsci_s3_005_c', 'q_bece_intsci_s3_005', 'c', 'Explain why a tiny organism such as Amoeba does not need a special transport system, but a human being does.', '2', 'Amoeba is microscopic, so oxygen and nutrients reach every part of its single cell by diffusion over a very short distance (1). A human is large and made of many cells, so diffusion alone would be far too slow; a blood circulatory system is needed to carry materials quickly to all cells (1).', '3');
INSERT INTO _migration_619_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_619_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_619_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'bece-int-science-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned BECE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) AND NOT EXISTS (SELECT 1 FROM _migration_619_expected_parts p JOIN structured_question_parts sp ON sp.id = p.id WHERE NOT (sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_619_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO structured_question_parts (id, question_id, part_label, part_text, marks, correct_answer, explanation, answer_type, display_order) SELECT p.id, p.question_id, p.part_label, p.part_text, p.marks, p.correct_answer, NULL, 'text', p.display_order FROM _migration_619_expected_parts p WHERE NOT EXISTS (SELECT 1 FROM structured_question_parts sp WHERE sp.id = p.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'bece-int-science-sprint3-001', 'automated_beta', 'beta', 'Original BrillaPrep curriculum-aligned BECE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.', 'https://nacca.gov.gh/common-core-programme-ccp/', 0, 1 FROM _migration_619_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
INSERT INTO _migration_619_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_619_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 7 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_619_expected e ON e.id = r.question_id WHERE r.batch_id IS 'bece-int-science-sprint3-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned BECE Integrated Science practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/common-core-programme-ccp/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 7 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_619_expected e ON e.id = q.id) = 7 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_619_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 3 THEN 1 ELSE 0 END;
